package com.tihai.utils;
import com.tihai.common.Question;import com.tihai.constant.QueryResponseConstant;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.web.reactive.function.client.*;import org.springframework.http.HttpStatus;import reactor.core.publisher.Mono;import java.io.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class LearningTongAiTest {
 Question question(){Question q=new Question();q.setType("single");q.setTitle("测试题");q.setTKOptions(Arrays.asList("A. Alpha","B. Beta"));return q;}
 String event(String type,String content)throws Exception{Map<String,String> e=new LinkedHashMap<>();e.put("type",type);e.put("content",content);return new ObjectMapper().writeValueAsString(e);}
 @Test void parsesNativeStreamAndIgnoresFollowupAndReasoning()throws Exception{String wire=":server-heartbeat\ndata:"+event("reasoning_content","不应作为答案")+"\ndata:"+event("coreAnswer","{\"answers\":[")+"$_$"+event("coreAnswer","\"B\"]}")+"\ndata:"+event("follow_up","下一题");assertEquals("B. Beta",LearningTongAiClient.parseAnswer(new StringReader(wire),question()));}
 @Test void rejectsFreeTextUnknownLabelsAndPartialJson()throws Exception{for(String content:Arrays.asList("我认为A","{\"answers\":[\"Z\"]}","{\"answers\":["))assertThrows(IOException.class,()->LearningTongAiClient.parseAnswer(new StringReader(event("coreAnswer",content)),question()));}
 Query query(boolean bankHit,LearningTongAiClient platform,DeepSeekClient deep,LiveProgressTracker tracker){Query q=new Query();WebClient bank=WebClient.builder().exchangeFunction(request->Mono.just(ClientResponse.create(HttpStatus.OK).header("Content-Type","application/json").body("{\"code\":"+QueryResponseConstant.SUCCESS_CODE+",\"data\":\""+(bankHit?"A. Alpha":"")+"\"}").build())).build();ReflectionTestUtils.setField(q,"tikuWebClient",bank);ReflectionTestUtils.setField(q,"learningTongAi",platform);ReflectionTestUtils.setField(q,"deepSeekClient",deep);ReflectionTestUtils.setField(q,"liveProgress",tracker);return q;}
 @Test void questionBankComesBeforeEitherAi()throws Exception{LearningTongAiClient platform=mock(LearningTongAiClient.class);DeepSeekClient deep=mock(DeepSeekClient.class);LiveProgressTracker tracker=new LiveProgressTracker();assertEquals("A. Alpha",query(true,platform,deep,tracker).queryAnswerSync(question()));verify(platform,never()).answer(any());verify(deep,never()).answer(any());}
 @Test void learningTongComesBeforeDeepSeekAndSetsProvenance()throws Exception{LearningTongAiClient platform=mock(LearningTongAiClient.class);when(platform.isEnabled()).thenReturn(true);when(platform.answer(any())).thenReturn("B. Beta");DeepSeekClient deep=mock(DeepSeekClient.class);LiveProgressTracker tracker=new LiveProgressTracker();tracker.begin("test");tracker.quiz("test",1);try{assertEquals("B. Beta",query(false,platform,deep,tracker).queryAnswerSync(question()));assertEquals("学习通 AI 已返回",tracker.snapshot("test").get("answer_source"));verify(deep,never()).answer(any());}finally{tracker.release();}}
 @Test void unavailableLearningTongFallsBackToConfiguredDeepSeek()throws Exception{LearningTongAiClient platform=mock(LearningTongAiClient.class);when(platform.isEnabled()).thenReturn(true);when(platform.answer(any())).thenThrow(new IOException("test"));DeepSeekClient deep=mock(DeepSeekClient.class);when(deep.isEnabled()).thenReturn(true);when(deep.answer(any())).thenReturn("A. Alpha");LiveProgressTracker tracker=new LiveProgressTracker();assertEquals("A. Alpha",query(false,platform,deep,tracker).queryAnswerSync(question()));verify(deep).answer(any());}
}
